import type {
  ArcangelRequest,
  ArcangelResponse,
} from "@arcangel/framework/http"
import { batchLinkProductsToCategoryWorkflow } from "@arcangel/arcangel/core-flows"

export async function POST(
  req: ArcangelRequest,
  res: ArcangelResponse
) {
  const { result } = await batchLinkProductsToCategoryWorkflow(req.scope)
    .run({
      input: {
        id: "pcat_123",
        add: ["prod_123"],
        remove: ["prod_321"]
      }
    })

  res.send(result)
}

